syntax:
Function returning an object by value, where the compiler can perform RVO/NRVO:

```c++
MyClass createObject() {
  MyClass obj; // Construction happens only once
  // ... some processing of obj
  return obj; // No copy/move construction
}
```

code_example:
#include <iostream>
#include <string>
struct MyClass {
  std::string data;
  MyClass(const std::string& d) : data(d) { std::cout << "MyClass constructed\n"; }
  MyClass(const MyClass& other) : data(other.data) { std::cout << "MyClass copy-constructed\n"; }
  MyClass(MyClass&& other) noexcept : data(std::move(other.data)) { std::cout << "MyClass move-constructed\n"; }
  ~MyClass() { std::cout << "MyClass destructed\n"; }
};
MyClass createObject() {
  MyClass obj("Hello");
  return obj;
}
int main() {
  MyClass myObj = createObject();
  return 0;
}
